/*
 * domain.js — the model's business logic, generated by the `prototype` skill from one context.
 * This example shows the contract runtime.js expects; replace every entry with the board's own.
 *
 * Plain JavaScript (no JSX, no imports) so it runs in the browser and under `node runtime.js domain.js`.
 */
(function (root) {
  const { reject } = typeof module !== 'undefined' && module.exports ? require('./runtime.js') : root.EMRuntime;

  // Helpers shared by deciders and projections — keep them small and named in the board's language.
  const ofType = (events, type) => events.filter((e) => e.type === type);

  const Domain = {
    context: 'Registration',

    // One entry per COMMAND. decide(history, command, ctx) returns the events to append or calls
    // reject('<errorDescription>') — every rule comes from a scenario on the board.
    commands: {
      RegisterCustomer: {
        slice: 'Register Customer',
        fields: [
          { name: 'customerId', type: 'UUID', generated: true },
          { name: 'name', type: 'String', example: 'Jane Doe' },
          { name: 'email', type: 'String', example: 'jane@example.com' },
        ],
        decide(history, cmd, ctx) {
          // Scenario: "Email must be unique"
          if (ofType(history, 'CustomerRegistered').some((e) => e.data.email === cmd.email)) {
            reject('Email is already registered');
          }
          return [
            {
              type: 'CustomerRegistered',
              data: { customerId: cmd.customerId || ctx.uuid(), name: cmd.name, email: cmd.email },
            },
          ];
        },
      },
      SendConfirmationMail: {
        slice: 'Send Confirmation Mail',
        fields: [{ name: 'customerId', type: 'UUID' }, { name: 'email', type: 'String' }],
        decide(history, cmd, ctx) {
          return [{ type: 'ConfirmationMailSent', data: { customerId: cmd.customerId, sentAt: ctx.now.toISOString() } }];
        },
      },
    },

    // One entry per READMODEL. evolve folds one event into the state; query (optional) shapes it
    // for a screen. Field names are the read model's attributes, verbatim.
    readModels: {
      Customers: {
        slice: 'Customer List',
        list: true,
        initial: () => [],
        evolve(state, e) {
          if (e.type === 'CustomerRegistered') return [...state, { customerId: e.data.customerId, name: e.data.name, email: e.data.email, confirmed: false }];
          if (e.type === 'ConfirmationMailSent') return state.map((c) => (c.customerId === e.data.customerId ? { ...c, mailSent: true } : c));
          return state;
        },
      },
      // An automation's todo list.
      PendingConfirmationMails: {
        slice: 'Send Confirmation Mail',
        list: true,
        initial: () => ({}),
        evolve(state, e) {
          if (e.type === 'CustomerRegistered') return { ...state, [e.data.customerId]: { customerId: e.data.customerId, email: e.data.email } };
          if (e.type === 'ConfirmationMailSent') {
            const { [e.data.customerId]: _done, ...rest } = state;
            return rest;
          }
          return state;
        },
        query: (state) => Object.values(state),
      },
    },

    // One entry per AUTOMATION. todo(readModelResult) lists the work; process(item) returns the
    // command to issue and, for a call into the outside world, the effect shown in the outbox.
    // trigger: 'auto' (runs as soon as events arrive) | 'schedule' (only on clock advance / Run now).
    automations: {
      SendConfirmationMail: {
        slice: 'Send Confirmation Mail',
        readModel: 'PendingConfirmationMails',
        trigger: 'auto',
        todo: (items) => items,
        process: (item) => ({
          effect: `E-mail with confirmation link to ${item.email}`,
          command: { type: 'SendConfirmationMail', data: { customerId: item.customerId, email: item.email } },
        }),
      },
    },

    // Events this context receives but never records itself (other contexts, external systems).
    // The prototype offers a "simulate" form for each.
    externalEvents: [
      // { type: 'PaymentReceived', from: 'Payments', fields: [{ name: 'orderId', type: 'UUID', example: '…' }] },
    ],

    // Every scenario on the board, one entry each. Leave generated values (ids, timestamps) out of
    // `then`/`expect` — only what the scenario names is compared.
    specs: [
      {
        slice: 'Register Customer',
        title: 'Customer registers',
        kind: 'command',
        given: [],
        when: { type: 'RegisterCustomer', data: { name: 'Jane Doe', email: 'jane@example.com' } },
        then: [{ type: 'CustomerRegistered', data: { name: 'Jane Doe', email: 'jane@example.com' } }],
      },
      {
        slice: 'Register Customer',
        title: 'Email must be unique',
        kind: 'command',
        given: [{ type: 'CustomerRegistered', data: { customerId: 'c-1', name: 'Jane Doe', email: 'jane@example.com' } }],
        when: { type: 'RegisterCustomer', data: { name: 'John Doe', email: 'jane@example.com' } },
        error: 'Email is already registered',
      },
      {
        slice: 'Customer List',
        title: 'Registered customers are listed',
        kind: 'readmodel',
        readModel: 'Customers',
        given: [{ type: 'CustomerRegistered', data: { customerId: 'c-1', name: 'Jane Doe', email: 'jane@example.com' } }],
        expect: [{ customerId: 'c-1', name: 'Jane Doe' }],
      },
      {
        slice: 'Send Confirmation Mail',
        title: 'A new registration gets a confirmation mail',
        kind: 'automation',
        automation: 'SendConfirmationMail',
        given: [{ type: 'CustomerRegistered', data: { customerId: 'c-1', name: 'Jane Doe', email: 'jane@example.com' } }],
        expectCommands: [{ type: 'SendConfirmationMail', data: { customerId: 'c-1' } }],
      },
    ],
  };

  if (typeof module !== 'undefined' && module.exports) module.exports = Domain;
  else root.Domain = Domain;
})(typeof globalThis !== 'undefined' ? globalThis : this);
